/** Every live (non-archived) workspace's subscription; feeds the renewal job. */
export async function listAllSubscriptions(): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/** Moves the subscription onto a new period, optionally changing plan/status. */
export async function updateSubscriptionPeriod(
  orgId: OrgId,
  patch: {
    readonly currentPeriodStart: IsoTimestamp;
    readonly currentPeriodEnd: IsoTimestamp;
    readonly plan?: PlanId;
    readonly interval?: BillingInterval;
    readonly status?: Subscription["status"];
    readonly cancelAt?: IsoTimestamp | null;
  },
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}
