const logger = createLogger("billing-renewal-job");

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listAllSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const changed = await processSubscription(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processSubscription(
  initial: Subscription,
  now: Date,
): Promise<boolean> {
  const orgId = initial.orgId as OrgId;
  let subscription = initial;
  let changed = false;

  if (
    subscription.status === "canceled" &&
    subscription.cancelAt !== null &&
    new Date(subscription.cancelAt).getTime() <= now.getTime()
  ) {
    const from = subscription.plan;
    const start = new Date(subscription.cancelAt);
