      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from,
      to: "free",
    });
    changed = true;
  }

  if (subscription.status !== "active") return changed;

  while (new Date(subscription.currentPeriodEnd).getTime() <= now.getTime()) {
    const start = new Date(subscription.currentPeriodEnd);
    const end = periodEndFor(start, subscription.interval);
    const periodStart = subscription.currentPeriodEnd;
    const periodEnd = toIsoTimestamp(end);

    subscription = await subscriptionRepo.updateSubscriptionPeriod(orgId, {
