export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** Same day and time `months` later (UTC), clamped to the month's last day. */
export function addMonths(from: Date, months: number): Date {
  const total = from.getUTCFullYear() * 12 + from.getUTCMonth() + months;
  const year = Math.floor(total / 12);
  const month = total - year * 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const result = new Date(from.getTime());
  result.setUTCFullYear(year, month, Math.min(from.getUTCDate(), lastDay));
  return result;
}

export function periodEndFor(
  start: Date,
  interval: BillingInterval,
): Date {
  return addMonths(start, monthsInInterval(interval));
}

/** Full-period charge in cents for a plan, seat count and interval. */
export function fullPeriodCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/** Scales a full-period amount by started days left over days in the period. */
export function prorateCents(
  fullCents: number,
  periodStart: string,
  periodEnd: string,
  now: Date,
): number {
  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();
  const days = Math.max(1, Math.round((end - start) / MS_PER_DAY));
  const left =
    now.getTime() >= end
      ? 0
      : Math.ceil((end - now.getTime()) / MS_PER_DAY);
  return Math.floor((fullCents * left) / days);
}

